import type { Metadata } from "next";
import type { PageMeta } from "@/content/types";
import { site } from "@/content/site";

// Generated by app/opengraph-image.tsx. Page-level openGraph objects replace the
// inherited image, so it is referenced explicitly.
const ogImage = { url: "/opengraph-image", width: 1200, height: 630, alt: `${site.name}: ${site.tagline}` };

/** Per-page metadata with a canonical URL and matching Open Graph / Twitter fields. */
export function pageMetadata(
  { title, description }: PageMeta,
  path: string,
  options?: { absoluteTitle?: boolean },
): Metadata {
  const fullTitle = options?.absoluteTitle ? title : `${title} | ${site.name}`;
  return {
    title: options?.absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_US",
      url: path,
      title: fullTitle,
      description,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [ogImage],
    },
  };
}
